"""Reusable conversions for Meridian CRM legacy storage conventions."""

from datetime import date
from decimal import Decimal, ROUND_HALF_UP


_LEGACY_NULL_DATE = "00000000"


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO format."""
    if yyyymmdd is None or yyyymmdd in ("", _LEGACY_NULL_DATE):
        return None
    if len(yyyymmdd) != 8 or not yyyymmdd.isdigit():
        raise ValueError(f"Invalid legacy date: {yyyymmdd!r}")

    iso = f"{yyyymmdd[:4]}-{yyyymmdd[4:6]}-{yyyymmdd[6:8]}"
    date.fromisoformat(iso)
    return iso


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to the legacy YYYYMMDD format."""
    if iso is None or iso == "":
        return _LEGACY_NULL_DATE
    if len(iso) != 10 or iso[4] != "-" or iso[7] != "-":
        raise ValueError(f"Invalid ISO date: {iso!r}")

    date.fromisoformat(iso)
    return iso.replace("-", "")


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N flag to bool, treating blank as N."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to currency minor units, half-up."""
    if amount is None or amount == "":
        return 0

    effective_currency = "USD" if currency is None or currency == "" else currency
    exponent = 0 if effective_currency == "JPY" else 2

    decimal_amount = Decimal(str(amount))
    scaled = decimal_amount * (Decimal(10) ** exponent)
    return int(scaled.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
